import{_ as s,o,c as e,a0 as a}from"./chunks/framework.DsVhn5Vy.js";const g=JSON.parse('{"title":"第 8 章 · 执行优化：融合、图捕获与数据搬运","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/ch08.md","filePath":"chapters/ch08.md"}'),r={name:"chapters/ch08.md"};function n(i,t,d,p,h,l){return o(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="第-8-章-·-执行优化-融合、图捕获与数据搬运" tabindex="-1">第 8 章 · 执行优化：融合、图捕获与数据搬运 <a class="header-anchor" href="#第-8-章-·-执行优化-融合、图捕获与数据搬运" aria-label="Permalink to &quot;第 8 章 · 执行优化：融合、图捕获与数据搬运&quot;">​</a></h1><p>前两章优化的是<strong>算什么</strong>（跳块、少搬中间量）。本章优化的是<strong>怎么执行</strong>：同一段计算，为什么提交给设备的方式不同，时间就差很多？第 3 章的 profiler 已经给过预告——<code>view</code>/<code>as_strided</code> 这类&quot;元数据算子&quot;调用了上千次。本章的问题是：<strong>一次前向被切成的几千个小步骤，每一步的&quot;提交&quot;本身要花多少钱？这笔钱怎么省？</strong></p><p>三个治理对象对应三节：小算子的提交开销（8.1/8.2 融合）、整段执行图的重复提交（8.3 CUDA Graph）、搬运与同步的交错（8.4）。实验在 <code>experiments/exp_ch8_exec/</code>。本机无 NVIDIA GPU：CPU 侧机制与相对量级实测签收，<strong>设备端行为（真实图捕获、私有内存池、H2D）一律标&quot;未测&quot;</strong>（5.3），代码按官方约束就绪交付。</p><h2 id="_8-1-一段执行的四层时间-提交、启动、计算、等待" tabindex="-1">8.1 一段执行的四层时间：提交、启动、计算、等待 <a class="header-anchor" href="#_8-1-一段执行的四层时间-提交、启动、计算、等待" aria-label="Permalink to &quot;8.1 一段执行的四层时间：提交、启动、计算、等待&quot;">​</a></h2><p>把&quot;模型跑一步&quot;拆开看，时间花在四个不同的地方：</p><table tabindex="0"><thead><tr><th>层</th><th>发生在哪</th><th>本机可测？</th></tr></thead><tbody><tr><td><strong>CPU 提交</strong></td><td>Python → ATen 分发、参数检查、shape 推导</td><td>✓</td></tr><tr><td><strong>kernel 启动</strong></td><td>驱动把算子放进设备队列</td><td>CUDA 上显著，CPU 并入提交</td></tr><tr><td><strong>设备计算</strong></td><td>算子真正执行</td><td>CPU 上与提交交织</td></tr><tr><td><strong>同步等待</strong></td><td>等 GPU/等传输/等另一个线程</td><td>✓（线程间）</td></tr></tbody></table><p><strong>实测每个小算子的提交开销</strong>（X2）：对 <code>[64]</code> 张量做 1000 次逐元素加法 vs 一次加上 1000.0 的塌缩单算子，差值除以 1000——<strong>≈2.1 µs/算子</strong>（本机 CPU，双方预热+成对交错 7 轮）。单看微不足道；但第 3 章 E4 里一次 decode 循环有近千次算子调用，一次 prefill 更多——<strong>提交开销 ≈ 算子数 × 2.1 µs</strong>，这就是&quot;小算子多到一定程度，Python 层调度盖过计算本身&quot;的算术。</p><p><strong>改动由 trace 指向</strong>（验收要求）：X1 用 <code>torch.profiler</code> 采集一段 50 次重复的小算子链（mm→silu→mul→mm），top-8 表存档（<code>x1_profiler_top8.txt</code>）——元数据/分发类算子占 self 时间 3–4%，数值计算本体外还有一整层可削的&quot;账面工作&quot;。这与第 3 章&quot;先看结构再下结论&quot;是同一条纪律：<strong>先采 trace，再选优化对象，不凭感觉融合</strong>。</p><h2 id="_8-2-融合-少一次中间读写-少一次提交" tabindex="-1">8.2 融合：少一次中间读写，少一次提交 <a class="header-anchor" href="#_8-2-融合-少一次中间读写-少一次提交" aria-label="Permalink to &quot;8.2 融合：少一次中间读写，少一次提交&quot;">​</a></h2><p>融合的原理第 6 章已经用过（FlashAttention 把三个算子融进一个内核）。这里用最小的两算子例子把<strong>收益与代价</strong>都摆出来——SwiGLU 的中间乘法（第 2 章 2.3）：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> silu(gate(x))     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 物化中间量 [T, d_ff]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> h </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> up(x)         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 再物化一个 [T, d_ff]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">out </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> down(h)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>两个连续算子 <code>silu</code> 与 <code>mul</code> 各自提交、各自把 <code>[T,d_ff]</code> 写一遍再读回来。<strong>融合的理想界</strong>：一个内核内完成，中间量留在寄存器——0 次物化。本书用<strong>可测的代理</strong>量化两头之间的距离（X3，T=32、d_ff=176、fp32）：</p><table tabindex="0"><thead><tr><th>变体</th><th>中间物化</th><th>时间（同机相对）</th></tr></thead><tbody><tr><td>out-of-place（两次物化）</td><td>2 × [32,176] fp32 = 45,056 B</td><td>0.091 ms</td></tr><tr><td>in-place（<code>h.mul_(up(x))</code>，一次物化）</td><td>22,528 B</td><td>0.080 ms</td></tr><tr><td>融合理想界</td><td>0 B</td><td>未测（无编译器/设备）</td></tr></tbody></table><p>三个诚实的读数：<strong>字节账如预期减半</strong>（2→1 个中间张量）；<strong>成对交错计时下 in-place 快约 12%</strong>——方向符合预期，但时间收益远小于字节减半的比例：CPU 分配器缓存下&quot;少物化一个张量&quot;近乎免费，省下的主要是分配与一遍读写；<strong>真融合内核本机不可得</strong>——<code>torch.compile</code> 报&quot;找不到 C++ 编译器（cl）&quot;，如实记为缺项（环境缺项与探测代码错误已区分记录）。这组数字的教学价值恰恰在量级感：融合改善的是&quot;中间量往返 + 提交次数&quot;，前者在 HBM 受限的设备上是硬收益（第 6 章 F2 已证内存口径），后者是 8.1 的 2.1 µs × 削掉的算子数——CPU 小尺度上两者都只给出温和的相对收益。<strong>融合的可用条件</strong>也随之清楚：数值等价可验证（本例 allclose 逐位成立）、shape 固定或可特化、内核确实存在（编译器或手写）——三者缺一，融合只是愿望。</p><h2 id="_8-3-cuda-graph-把-整段提交-变成-一次重放" tabindex="-1">8.3 CUDA Graph：把&quot;整段提交&quot;变成&quot;一次重放&quot; <a class="header-anchor" href="#_8-3-cuda-graph-把-整段提交-变成-一次重放" aria-label="Permalink to &quot;8.3 CUDA Graph：把&quot;整段提交&quot;变成&quot;一次重放&quot;&quot;">​</a></h2><p>即使算子已经很好，decode 每步仍要重新提交几百个算子。CUDA Graph 的思路：<strong>第一次老老实实执行并把整段算子调用录制成图，之后每次只提交&quot;重放&quot;这一个动作</strong>——官方文档的约束清单（references S26）就是它的代价表：</p><ol><li><strong>捕获须在非默认流</strong>，且捕获前在 side stream 上预热（线程池、惰性初始化都留在预热里）；</li><li><strong>动态 shape 与 CPU 侧控制流禁止</strong>——每次重放&quot;读写同一（虚拟）内存地址&quot;，shape 变了图就错了；</li><li><strong>静态输入/输出缓冲</strong>：新数据 <code>static_input.copy_(x)</code> 喂进去、从捕获时的输出缓冲读出来——这部分<strong>额外内存</strong>是图的重放语义决定的；</li><li>捕获期间禁止 <code>.item()</code> 等 CPU-GPU 同步；API 尚属 beta。</li></ol><p>本书交付的 <code>cuda_graph_ready.py</code> 把这套工作流写成<strong>设备分支守卫</strong>的代码：<code>CudaGraphRunner</code> 在 CUDA 可用时走&quot;side-stream 预热 → <code>torch.cuda.graph</code> 捕获 → <code>copy_</code> 喂入 → <code>replay()</code>&quot;，输入签名（shape/dtype/device）变化时<strong>显式重捕获</strong>而不是静默出错；CPU 上捕获路径显式拒绝（报错信息说明原因），调用走可观测的 eager 回退计数。本机自检（X4）：<code>graphed=False</code>（未捕获，如实），回退计数与静态缓冲记账（本例 512 B）工作正常，动态 shape 的拒绝路径有断言。</p><p><strong>图与编译分别计量</strong>（验收条款）：CUDA Graph 治理的是<strong>提交/启动次数</strong>（同一段算子，一次提交），编译/融合治理的是<strong>算子本身的数量与形态</strong>——两者独立起效、收益可乘也可互斥（编译产物若含动态分支就不可捕获）。设备端两者的真实收益本机未测；CPU 侧能测的是它们共同治理的对象——8.1 的每算子 2.1 µs，乘以一步 decode 的算子数就是图重放在 CUDA 上的期望收益量级（真实数字须设备实测）。</p><h2 id="_8-4-数据搬运与同步-让-等-和-算-重叠" tabindex="-1">8.4 数据搬运与同步：让&quot;等&quot;和&quot;算&quot;重叠 <a class="header-anchor" href="#_8-4-数据搬运与同步-让-等-和-算-重叠" aria-label="Permalink to &quot;8.4 数据搬运与同步：让&quot;等&quot;和&quot;算&quot;重叠&quot;">​</a></h2><p>主机—设备传输是第四类成本。没有 GPU 时它的机制仍可以用 CPU 讲清楚，因为本质相同：<strong>搬运与计算是两份资源，同步点决定它们能不能重叠</strong>。X5 的双线程流水线（生产者造数据、消费者算，24 批）做了两组对照：</p><table tabindex="0"><thead><tr><th>生产者</th><th>串行交接</th><th>预取队列（深度 2）</th><th>相对</th></tr></thead><tbody><tr><td>纯计算（小算子）</td><td>0.0502 s</td><td>0.0442 s</td><td><strong>1.14×</strong></td></tr><tr><td>阻塞 I/O（写读磁盘）</td><td>0.1390 s</td><td>0.1047 s</td><td><strong>1.33×</strong></td></tr></tbody></table><p>两个变体一正一负，正好把机制讲透：<strong>重叠的前提是有一方真正在&quot;等&quot;</strong>。纯计算生产者与消费者都抢同一个 intra-op 线程池——串行时每个算子已经多核并行了，重叠空间所剩无几（1.14×，远低于理想 2×）；阻塞 I/O 生产者（磁盘写读、释放 GIL——DMA 传输的 CPU 类比）在串行时让计算侧干等，预取队列把&quot;等 I/O&quot;与&quot;算上一批&quot;叠起来，1.33×。映射到 GPU 场景：<code>to(device, non_blocking=True)</code> 配 pinned memory 让 H2D 由 DMA 引擎搬、计算单元同时算上一批——<strong>同一纪律，未测设备</strong>（按官方文档登记口径）。减少无意义同步的另一面：每个 <code>cuda.synchronize()</code>/<code>.item()</code> 都是把流水线打回串行的接缝——第 3 章计时纪律要求&quot;只在读表前同步&quot;，在生成循环里就是&quot;别每步都取数回 CPU&quot;。</p><h2 id="动手与验收" tabindex="-1">动手与验收 <a class="header-anchor" href="#动手与验收" aria-label="Permalink to &quot;动手与验收&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在解压后的 pi-infer-labs 目录中执行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments/exp_ch8_exec/cuda_graph_ready.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --self-check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # CPU 自检：守卫/回退/shape 拒绝</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments/exp_ch8_exec/run_exec_experiment.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # X1–X5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li><strong>X1</strong> trace 证据（profiler top-8 表，优化对象由 trace 指向）；<strong>X2</strong> 每算子提交开销 ≈2.1 µs（1000 算子链 vs 塌缩单算子）；<strong>X3</strong> 融合代理：out-of-place vs in-place（<code>torch.equal</code> 逐位一致 ✓、字节 2:1、成对交错计时 0.091→0.080 ms）+ torch.compile 缺项记录（环境缺项与代码错误区分）；<strong>X4</strong> CUDA Graph 代码就绪（守卫/动态 shape 重捕获/静态缓冲记账 512 B）+ 官方约束清单核对；<strong>X5</strong> 传输重叠：计算生产者 1.03× vs I/O 生产者 1.30×。</li><li>验收对照基准条款：对同一段执行做融合或图重放优化——本书完成的是<strong>代码就绪 + CPU 可测部分</strong>；比较 CPU 时间与（模拟的）提交次数；检查输出（X3 allclose）、动态 shape 回退（X4 显式重捕获分支）和额外内存（静态缓冲字节记账）。<strong>只做 trace 指向的改动</strong>（X1 先行）。</li></ul><p><strong>降级声明（5.3）</strong>：CUDA Graph 真实捕获/重放、GPU 私有内存池、H2D/pin_memory/non_blocking、torch.compile 融合内核——全部<strong>未测</strong>（无 NVIDIA GPU / 缺 MSVC）；X2/X3/X5 为同机相对对照，只支撑机制与量级结论，不外推设备性能。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><p><strong>练习 1</strong>：一步 decode 有 800 个算子调用，其中 200 个是 <code>view</code>/<code>reshape</code> 类元数据操作。按本章实测每算子 2.5 µs，仅提交开销是多少？若图重放把整步变成一次提交，省多少？答：800×2.1 µs=1.7 ms/步；TPOT 若为 20 ms，提交占 10%。图重放把这 2.0 ms 压到一次提交（µs 级），省 ≈10%——但注意重放不减少<strong>设备端计算</strong>，若瓶颈在计算（大 batch），收益按比例缩水：<strong>提交开销占比多大，图收益才多大</strong>。</p><p><strong>练习 2</strong>：为什么 CUDA Graph 要求静态 shape 与静态内存，而 PyTorch eager 不要求？答：eager 每次调用都重新分配、重新传参——慢但任意 shape 都行；图把&quot;哪段内存被哪个算子读写&quot;固化在录制里，重放只是让设备按录制的地址序列再跑一遍——地址变了内容就错。所以引擎用图要配合 padding 到固定长度或按 bucket 捕获多张图，这正是 X4 显式重捕获分支存在的意义。</p><p><strong>练习 3</strong>：X3 里 in-place 只快了 12%，而字节省了一半。有人说&quot;融合的收益被夸大了&quot;。对吗？答：半对——<strong>收益必须按资源维度分开报</strong>：字节维度 in-place 实打实省 50%（45,056→22,528 B），时间维度只省 12%（分配器缓存下物化近乎免费，省的是一遍读写）；融合（把中间量留在寄存器）在 CPU 小尺度上与 in-place 同一量级，其&quot;字节省 100%&quot;的完整收益要 HBM 受限的设备才兑现（第 6 章 F2 内存口径）。<strong>&quot;优化&quot;从来是&quot;在哪个资源维度上省多少&quot;，不是单一&quot;快不快&quot;</strong>。</p><p><strong>练习 4</strong>：把 X5 的消费者改成每消费一批就 <code>queue.task_done()</code> 并等待生产者的下一批（严格锁步），预期流水收益如何变化？答：趋近 1.0×（串行交接的等价物）——锁步等于在每个边界插入同步点，&quot;等&quot;与&quot;算&quot;不再重叠。预取队列的收益来自深度允许的错峰：消费者永远有活干，生产者的阻塞被藏进消费时间。深度也不是越大越好：内存占用与首批延迟随深度增长。</p><p><strong>练习 5</strong>：一条生产建议说&quot;把循环里所有 <code>.item()</code> 都删掉&quot;。给出一个不能删的反例。答：停止条件——<code>next_id == eos_id</code> 的判断必须把 argmax 结果拿回 CPU（<code>.item()</code>），否则循环无法终止。正确的治理是<strong>减少同步点的个数</strong>而不是消灭：每步一次（判断停止）是必要的，每步多次（日志、指标、调试打印）才是被治理的对象；投机解码（第 7 章）一次前向换多个 token，恰好也把&quot;每 token 一次的 CPU 交互&quot;摊薄了。</p><h2 id="小结-算了什么、慢在哪里、怎样验证" tabindex="-1">小结：算了什么、慢在哪里、怎样验证 <a class="header-anchor" href="#小结-算了什么、慢在哪里、怎样验证" aria-label="Permalink to &quot;小结：算了什么、慢在哪里、怎样验证&quot;">​</a></h2><ul><li>一段执行的时间=提交+启动+计算+等待四层；小算子提交开销实测 ≈2.5 µs/个，机制上由融合（减少算子数）与 CUDA Graph（减少提交次数）分别治理——两者独立计量、可叠加；</li><li>融合的收益维度是中间物化字节与提交次数，可用条件是数值等价+shape 固定+内核存在；本机代理实验显示 CPU 时间维度无收益（如实报告），字节维度收益真实；</li><li>CUDA Graph 的约束（静态 shape/内存、side-stream 预热、静态缓冲喂入）就是它的代价表；代码就绪交付、设备行为未测；图治提交、编译治算子形态——分别计量不混谈；</li><li>搬运与同步：重叠的前提是一方真正阻塞（I/O/DMA），纯计算双线程只是竞争；同步点是流水的接缝，能少则少、必要的（停止判断）保留。</li></ul><p>下一章从单次执行走向多请求：批处理与调度——当很多请求同时到达，谁来决定下一步算谁的 token。</p><h2 id="本章出处" tabindex="-1">本章出处 <a class="header-anchor" href="#本章出处" aria-label="Permalink to &quot;本章出处&quot;">​</a></h2><p>CUDA Graph 约束与 API 行为 S26（PyTorch 官方 CUDA notes，torch 2.15）；H2D/pin_memory/non_blocking 语义同据 S26 登记、本机未测。每算子提交开销、融合代理、流水线对照均为本章实测（<code>experiments/exp_ch8_exec/raw.json</code>，含 profiler 表与复跑命令）。</p>`,38)])])}const u=s(r,[["render",n]]);export{g as __pageData,u as default};
